"""Bidirectional cross-check (S1 §1.0): vectors generated by upstream Go verify in levain's Python.

``tests/golden/contracts/xcheck`` writes them with ``go run . -emit FILE ../frozen`` (``note.Sign``,
``formats/log`` checkpoints, ``formats/note`` cosignature/v1 signers, the ``merkle/testonly`` tree). This file
reads FILE from ``LEVAIN_XCHECK_EMIT``. Without it the tests skip; the xcheck CI job sets
``LEVAIN_REQUIRE_XCHECK=1``, which turns that skip into a failure.
"""
import json
import os
from pathlib import Path

import pytest

from levain.contracts import checkpoint as C, merkle as M, note as N

_PATH = os.environ.get("LEVAIN_XCHECK_EMIT")
if not _PATH and os.environ.get("LEVAIN_REQUIRE_XCHECK") == "1":
    raise RuntimeError("LEVAIN_REQUIRE_XCHECK=1 but LEVAIN_XCHECK_EMIT is not set")
pytestmark = pytest.mark.skipif(not _PATH, reason="no Go-generated vectors (set LEVAIN_XCHECK_EMIT)")
DOC = json.loads(Path(_PATH).read_text()) if _PATH else {}


def _h(x):
    return bytes.fromhex(x)


def test_the_emitted_file_has_every_section():
    for k in ("notes", "checkpoints", "cosigned", "inclusion", "consistency"):
        assert DOC[k], k


def test_go_signed_notes_verify():
    for g in DOC["notes"]:
        _, good = N.verify(g["note"], [N.parse_vkey(k) for k in g["vkeys"]])
        assert len(good) == len(g["vkeys"])


def test_go_checkpoint_verifies_as_a_team_log():
    for g in DOC["checkpoints"]:
        cp, _ = C.verify(g["note"], N.parse_vkey(g["vkeys"][0]), team=True)
        leaves = [bytes([i % 256]) * (i + 1) for i in range(cp.size)]
        assert cp.root == M.root(leaves)


def test_go_cosignatures_verify_to_records():
    for g in DOC["cosigned"]:
        recs = C.verify_cosignatures(g["note"], [N.parse_vkey(k) for k in g["vkeys"]], g["now"])
        assert [r.cosigner_name for r in recs] == [k.split("+")[0] for k in g["vkeys"]]


def test_go_merkle_proofs_verify():
    for g in DOC["inclusion"]:
        M.verify_inclusion(g.get("index", 0), g["size"], _h(g["leaf_hash"]), [_h(p) for p in g["proof"]], _h(g["root"]))
    for g in DOC["consistency"]:
        M.verify_consistency(g["m"], g["size"], [_h(p) for p in g["proof"]], _h(g["old_root"]), _h(g["root"]))
